// AuthServiceHandler is an implementation of the he.auth.v1.AuthService service.
type AuthServiceHandler interface {
	RegisterUser(context.Context, *connect.Request[v1.RegisterUserRequest]) (*connect.Response[v1.RegisterUserResponse], error)
	VerifyEmail(context.Context, *connect.Request[v1.VerifyEmailRequest]) (*connect.Response[v1.VerifyEmailResponse], error)
	ResendVerification(context.Context, *connect.Request[v1.ResendVerificationRequest]) (*connect.Response[v1.ResendVerificationResponse], error)
	LoginUser(context.Context, *connect.Request[v1.LoginUserRequest]) (*connect.Response[v1.LoginUserResponse], error)
	RefreshToken(context.Context, *connect.Request[v1.RefreshTokenRequest]) (*connect.Response[v1.RefreshTokenResponse], error)
	// Story 2.3 — OAuth (Google + GitHub) Authorization Code + PKCE flow.
	// BeginOAuth: generate state + PKCE verifier, persist to Redis (TTL=600s
	// GETDEL one-shot per Wright Round 1 Q1=(a)), return provider authorize URL.
	// CompleteOAuth: redeem code+state, validate provider token, execute
	// verify-only auto-link decision (Wright Round 1 Q2=(a); 10 branches per
	// BR-3.1..BR-3.10), issue JWT (Story 2.2 jwt pkg) or 2FA challenge.
	BeginOAuth(context.Context, *connect.Request[v1.BeginOAuthRequest]) (*connect.Response[v1.BeginOAuthResponse], error)
	CompleteOAuth(context.Context, *connect.Request[v1.CompleteOAuthRequest]) (*connect.Response[v1.CompleteOAuthResponse], error)
	// Story 2.4 — TOTP 2FA (RFC 6238 + recovery codes + KMS envelope).
	// EnrollTOTPInit: generate 160-bit secret + 10 recovery codes, KMS-encrypt,
	// stage in Redis (auth:2fa:enroll:{user_id}, TTL=600s GETDEL one-shot),
	// return otpauth_uri + QR + plaintext recovery codes (only response that
	// returns them).
	// EnrollTOTPVerify: consume staged enrollment, validate first TOTP code,
	// persist totp_secret_encrypted + 10 bcrypt-hashed recovery codes in a
	// single PG transaction. Out-of-band 2fa_enabled email.
	// ChallengeTOTP: validates mfa_token (short-lived RS256 JWT, purpose=
	// '2fa_challenge') + 6-digit code, issues full-session access+refresh
	// tokens with aal=2 claim. Single-use JTI (Redis DEL on success).
	// UseRecoveryCode: alternative to ChallengeTOTP — bcrypt-compares input
	// against unused mfa_recovery_codes rows, atomic mark-used, issues aal=2
	// session tokens. Out-of-band 2fa_recovery_used email.
	// DisableTOTP: clears totp_secret_encrypted + deletes all recovery codes,
	// requires aal=2 session + factor re-verification (TOTP or password).
	// Out-of-band 2fa_disabled email (HIGH severity).
	// RegenerateRecoveryCodes: marks all current unused codes as used (forensic
	// trail) + issues 10 fresh codes in a single PG transaction. Requires
	// aal=2 + factor re-verification.
	EnrollTOTPInit(context.Context, *connect.Request[v1.EnrollTOTPInitRequest]) (*connect.Response[v1.EnrollTOTPInitResponse], error)
	EnrollTOTPVerify(context.Context, *connect.Request[v1.EnrollTOTPVerifyRequest]) (*connect.Response[v1.EnrollTOTPVerifyResponse], error)
	ChallengeTOTP(context.Context, *connect.Request[v1.ChallengeTOTPRequest]) (*connect.Response[v1.ChallengeTOTPResponse], error)
	UseRecoveryCode(context.Context, *connect.Request[v1.UseRecoveryCodeRequest]) (*connect.Response[v1.UseRecoveryCodeResponse], error)
	DisableTOTP(context.Context, *connect.Request[v1.DisableTOTPRequest]) (*connect.Response[v1.DisableTOTPResponse], error)
	RegenerateRecoveryCodes(context.Context, *connect.Request[v1.RegenerateRecoveryCodesRequest]) (*connect.Response[v1.RegenerateRecoveryCodesResponse], error)
	// Story 2.5 — profile management.
	// GetMe: profile read for Settings → Profile (returns whole-user snapshot
	// including email + totp_enabled + oauth_provider so the page renders
	// without a second RTT). api-gateway populates user_id from the verified
	// JWT `sub` claim; clients NEVER supply it (BR-1.1 IDOR defence).
	// UpdateProfile: partial profile mutation (display_name / locale /
	// timezone). Optimistic concurrency via `if_match` etag = updated_at
	// UnixMicro() string (Architect Q2 ruling 2026-05-16). On
	// successful locale change, api-gateway also rewrites `he_locale` cookie
	// so next-intl reflects the new locale on next render (Architect Q3).
	GetMe(context.Context, *connect.Request[v1.GetMeRequest]) (*connect.Response[v1.GetMeResponse], error)
	UpdateProfile(context.Context, *connect.Request[v1.UpdateProfileRequest]) (*connect.Response[v1.UpdateProfileResponse], error)
	// Story 3.2 — API Key validation for the api-gateway Bearer-auth middleware.
	// Called per request on cache miss; bcrypt-compares the supplied plaintext
	// against api_keys rows matching the 12-char key_prefix. Returns ok=true
	// with identity + scope on match; ok=false with REASON for not-found /
	// revoked. Plaintext key MUST NOT appear in logs, span attributes, or
	// errors — AC2 BR-2.6 + docs/architecture/coding-standards.md §12.3.
	ValidateApiKey(context.Context, *connect.Request[v1.ValidateApiKeyRequest]) (*connect.Response[v1.ValidateApiKeyResponse], error)
	// Story 5.1 — API Key management surface (Create / List / Revoke).
	//
	// CreateApiKey: crypto/rand 32B → base62 → "he-" prefix → bcrypt(cost=12)
	// hash → INSERT he_api.api_keys → Kafka audit.event api_key.created.
	// Response carries the plaintext key ONCE (BR-1.5). user_id is gateway-
	// populated from JWT sub (BR-1.3 IDOR defence); client-supplied values
	// REJECTED.
	//
	// ListApiKeys: SELECT user-bound keys (LIMIT 100; ORDER BY created_at
	// DESC, id ASC). key_hash explicitly OMITTED from SELECT (BR-2.5 defence-
	// in-depth at the SQL boundary).
	//
	// RevokeApiKey: idempotent terminal-state UPDATE SET revoked_at=NOW();
	// sentinel SET auth:apikey:revoked:{api_key_id} EX 300 for cross-pod
	// cache-invalidation (BR-3.8; Architect Q2 ratified option-c). Returns
	// historical revoked_at + was_already_revoked on idempotent re-revoke.
	// Anti-enumeration: cross-user / not-found collapse to same NotFound
	// (BR-3.2; Architect Q4 ratified collapse).
	CreateApiKey(context.Context, *connect.Request[v1.CreateApiKeyRequest]) (*connect.Response[v1.CreateApiKeyResponse], error)
	ListApiKeys(context.Context, *connect.Request[v1.ListApiKeysRequest]) (*connect.Response[v1.ListApiKeysResponse], error)
	RevokeApiKey(context.Context, *connect.Request[v1.RevokeApiKeyRequest]) (*connect.Response[v1.RevokeApiKeyResponse], error)
	// Story 5.2 — API Key configuration (partial update of scope + cost cap).
	//
	// UpdateApiKey: partial-update of api_keys.scope (models[] + ip_whitelist[])
	// and monthly_cost_cap_usd. Only fields PRESENT in the patch mutate
	// (BR-1.7 merge semantics). SELECT ... FOR UPDATE re-asserts ownership +
	// revoke-state (anti-enumeration NotFound collapse per BR-1.8 cascade from
	// Story-5.1 BR-3.2); the UPDATE WHERE clause re-asserts revoked_at IS NULL
	// against TOCTOU. On commit: SET auth:apikey:config_updated:{api_key_id}
	// sentinel EX 300 for cross-pod cache-invalidation (BR-1.9; mirrors the
	// Story-5.1 revoke sentinel) + Kafka audit.event api_key.config_updated
	// (BR-1.11; PII-safe; changed_fields[]). users.status='pending_deletion'
	// → FailedPrecondition account_pending_deletion (Q-I). No updated_at write
	// (Architect Q-K — the schema has no such column).
	UpdateApiKey(context.Context, *connect.Request[v1.UpdateApiKeyRequest]) (*connect.Response[v1.UpdateApiKeyResponse], error)
	// Story 5.4 (Architect Round 1 Q-L Fix-A) — internal lookup feeding the
	// notification-svc monthly-cap email path. notification-svc cannot import
	// auth-svc's internal/repository across the go.work module boundary, so
	// auth-svc (the sole canonical reader of the PII-sensitive api_keys table)
	// exposes the JOIN result over gRPC. Single PG round-trip; called
	// fire-and-forget off the gateway hot path.
	GetCapNotificationContext(context.Context, *connect.Request[v1.GetCapNotificationContextRequest]) (*connect.Response[v1.GetCapNotificationContextResponse], error)
	// Story 2.7 — GDPR account deletion (30-day grace). Added to the EXISTING
	// auth service (BR-2.2), NOT a new service.
	//
	// RequestAccountDeletion: re-auth-gated active→pending_deletion transition
	// (OWASP ASVS L2 V8.3). Server-side re-verifies a fresh credential
	// (password / confirm_email for OAuth-only / +TOTP when totp_enabled),
	// single-winner CAS `UPDATE ... WHERE id=$1 AND status='active'`, sets
	// pending_deletion_at = NOW() + 30d (server UTC, never client-supplied),
	// revokes all sessions, audits account.deletion.requested, fires
	// EMAIL_TEMPLATE_ACCOUNT_DELETION_REQUESTED. Idempotent: a 2nd request while
	// already pending returns the SAME pending_deletion_at (no new audit/email).
	// user_id is gateway-populated from JWT sub (BR-2.4 IDOR defence).
	//
	// CancelAccountDeletion: restorative pending_deletion→active CAS during the
	// grace window. Requires ONLY a valid JWT — no fresh re-auth (OQ-2 ratified
	// asymmetry; deletion is destructive, cancellation is restorative and is
	// already gated by signin). 0 rows + grace expired/deleted → grace_expired.
	//
	// GetAccountDeletionState: read-only hydration for AC1 dialog field
	// branching (has_password / totp_enabled are server-authoritative; the
	// password hash NEVER leaves auth-svc) + AC3 recovery countdown + AC4 guard.
	RequestAccountDeletion(context.Context, *connect.Request[v1.RequestAccountDeletionRequest]) (*connect.Response[v1.RequestAccountDeletionResponse], error)
	CancelAccountDeletion(context.Context, *connect.Request[v1.CancelAccountDeletionRequest]) (*connect.Response[v1.CancelAccountDeletionResponse], error)
	GetAccountDeletionState(context.Context, *connect.Request[v1.GetAccountDeletionStateRequest]) (*connect.Response[v1.GetAccountDeletionStateResponse], error)
}

